fn _json_is_null(v: JsonValue) bool   { return v == .null; }
fn _json_is_object(v: JsonValue) bool  { return switch (v) { .object => true, else => false }; }
fn _json_is_array(v: JsonValue) bool   { return switch (v) { .array  => true, else => false }; }
