    nodes: std.ArrayListUnmanaged(_RNode) = .{ .items = &.{}, .capacity = 0 }, alloc: std.mem.Allocator, n_caps: u8 = 0, flags: _RFlags = .{},
    fn addNode(c: *_RC, n: _RNode) error{OutOfMemory}!u32 {
